    ('SelectiveEndgamePlayer.py', '"""Experimental v1.2: v5 guidance, bounded win/loss proof, v5 fallback.\n\nNo evaluation changes, opening database, heuristic proof labels, or promotion.\nAt <=20 stones and <=24 legal moves: 10% of the clock for v5 guidance,\nup to 50% for a terminal-outcome solver, then remaining time for v5 if unknown.\nCompleted proofs survive turns in two bounded generations. A proof of loss\ndoes not replace v5\'s choice among losing moves. All phases share one deadline.\n"""\nfrom dataclasses import replace\nimport time\nimport player_versions.verified_denial_08.challengers.LeafV5 as v5\nfrom player_versions.verified_denial_08.GameCore import from_state, generate, decode, encode, terminal_diff\n\nConfig = v5.Config\nVERSION = \'selective-endgame-v12-experimental\'\nPROOF_ENTRIES = 100000\nNORMAL_ENTRIES = 50000\nWIN_BIT = 512\nNO_MOVE = 511\n\n\ndef proof_key(pos):\n    # Capture score is essential for win/loss facts, unlike exact remaining swing.\n    return bytes(pos.board)+bytes((int(pos.turn==1), pos.diff+36))\n\n\ndef unpack(record):\n    move = record & 511\n    return bool(record & WIN_BIT), None if move == NO_MOVE else move\n\n\nclass ProofTimeout(Exception):\n    pass\n\n\nclass ProofCache:\n    """Two generations; no hash-only matches and no unbounded third table."""\n    def __init__(self, capacity=PROOF_ENTRIES):\n        if capacity < 2: raise ValueError(\'Proof capacity must be at least two\')\n        self.half = capacity//2\n        self.new = {}; self.old = {}; self.rotations = 0\n\n    def get(self, key):\n        record = self.new.get(key)\n        return self.old.get(key) if record is None else record\n\n    def put(self, key, won, move):\n        record = (WIN_BIT if won else 0) | (NO_MOVE if move is None else move)\n        existing = self.get(key)\n        if existing is not None:\n            assert unpack(existing)[0] == won, \'Contradictory proof\'\n            return\n        if len(self.new) >= self.half:\n            self.old = self.new; self.new = {}; self.rotations += 1\n        self.new[key] = record\n\n    def __len__(self):\n        return len(self.new)+len(self.old)\n\n\nclass OutcomeSolver:\n    def __init__(self, cache, guidance=None):\n        self.cache = cache; self.guidance = guidance if guidance is not None else {}\n        self.stats = dict(nodes=0, hits=0, terminals=0, score_bounds=0)\n\n    def solve(self, pos, deadline, max_nodes=0, preferred=None):\n        if time.perf_counter() >= deadline or (max_nodes and self.stats[\'nodes\'] >= max_nodes):\n            raise ProofTimeout\n        self.stats[\'nodes\'] += 1\n        k = proof_key(pos); found = self.cache.get(k)\n        if found is not None:\n            self.stats[\'hits\'] += 1\n            return unpack(found)\n        edges = generate(pos)\n        if not edges:\n            light_wins = terminal_diff(pos) >= 0\n            answer = light_wins if pos.turn==1 else not light_wins\n            self.stats[\'terminals\'] += 1\n            self.cache.put(k, answer, None)\n            return answer, None\n        # Future captures plus the one final bonus cannot exceed remaining stones.\n        # This proves an outcome for EVERY continuation, including Light\'s tie.\n        remaining = sum(pos.board)\n        if pos.diff >= remaining or pos.diff < -remaining:\n            light_wins = pos.diff >= remaining\n            answer = light_wins if pos.turn==1 else not light_wins\n            self.stats[\'score_bounds\'] += 1\n            self.cache.put(k, answer, edges[0].move)\n            return answer, edges[0].move\n        if preferred is None:\n            entry = self.guidance.get(pos)\n            preferred = entry[3] if entry else None\n        edges.sort(key=lambda edge:(edge.move==preferred, edge.gain), reverse=True)\n        for edge in edges:\n            child_won, _ = self.solve(edge.child, deadline, max_nodes)\n            if not child_won:\n                # One losing opponent child proves our win. Other moves may stay unknown.\n                self.cache.put(k, True, edge.move)\n                return True, edge.move\n        # A loss requires every legal reply to have been proved winning for the opponent.\n        self.cache.put(k, False, edges[0].move)\n        return False, edges[0].move\n\n\nclass _Guidance(v5.Searcher):\n    def _start(self, seconds=None):\n        # Preserve the table when resuming the same move, even if it became full.\n        saved = self.table if getattr(self,\'resume\',False) else None\n        if saved is not None: self.table = {}\n        super()._start(seconds)\n        if saved is not None: self.table = saved\n        self.deadline = min(self.deadline, self.outer_deadline)\n\n\nclass Searcher:\n    def __init__(self, config=None, proof_capacity=PROOF_ENTRIES):\n        self.config = config or Config()\n        self.normal = _Guidance(replace(self.config, tt_size=min(self.config.tt_size,NORMAL_ENTRIES)))\n        self.proofs = ProofCache(proof_capacity)\n        self.stats = {}\n\n    def choose(self, state):\n        started = time.perf_counter()\n        budget = min(29.0, max(0,self.config.seconds))*.98\n        deadline = started+budget\n        pos = from_state(state); edges = generate(pos)\n        if not edges: raise ValueError(\'getMove called on terminal state\')\n        eligible = sum(pos.board)<=20 and len(edges)<=24\n        phases = []; move = decode(edges[0].move); value = None; proven = False\n        proof_won = None; proof_attempted = False; proof_seconds = 0.0\n        proof_stats = dict(nodes=0,hits=0,terminals=0,score_bounds=0)\n        normal_nodes = 0; proof_move = None; proof_reused = False\n        self.normal.outer_deadline = deadline\n        self.normal.resume = False\n\n        def normal_phase(stop):\n            nonlocal move, value, proven, normal_nodes\n            remaining = stop-time.perf_counter()\n            allowance = self.config.max_nodes-normal_nodes-proof_stats[\'nodes\'] if self.config.max_nodes else 0\n            if remaining<=0 or (self.config.max_nodes and allowance<=0): return\n            self.normal.outer_deadline = min(stop, deadline)\n            self.normal.config = replace(self.normal.config, seconds=remaining/.98, max_nodes=allowance)\n            move = self.normal.choose(state)\n            phase = dict(self.normal.stats); phases.append(phase)\n            normal_nodes += phase[\'nodes\']; value = phase[\'value\']; proven = phase[\'proven_outcome\']\n            self.normal.resume = True\n\n        cached = self.proofs.get(proof_key(pos))\n        if cached is not None:\n            proof_won, proof_move = unpack(cached); proof_reused = True\n        if proof_won is True:\n            assert proof_move in {edge.move for edge in edges}\n            move = decode(proof_move); proven = True\n        elif not eligible or proof_won is False:\n            normal_phase(deadline)\n        else:\n            normal_phase(started+budget*.1)\n            if not proven and time.perf_counter()<deadline:\n                solver = OutcomeSolver(self.proofs, self.normal.table)\n                proof_started = time.perf_counter()\n                allowance = self.config.max_nodes-normal_nodes if self.config.max_nodes else 0\n                if not self.config.max_nodes or allowance>0:\n                    proof_attempted = True\n                    try:\n                        proof_won, proof_move = solver.solve(pos, min(deadline, started+budget*.6),\n                                                           allowance, encode(move))\n                    except ProofTimeout:\n                        pass  # Completed descendants survive; interrupted parent stays unknown.\n                proof_stats = dict(solver.stats)\n                proof_seconds = time.perf_counter()-proof_started\n                if proof_won is True:\n                    move = decode(proof_move); proven = True\n                else:\n                    normal_phase(deadline)\n        elapsed = time.perf_counter()-started\n        if proof_won is True:\n            value = None  # An exact outcome is NOT an exact numeric margin.\n        proven = proven or proof_won is not None\n        fields = (\'nodes\',\'tt_hits\',\'tt_cutoffs\',\'cutoffs\',\'eval_calls\',\'terminal_nodes\',\'leaf_probes\',\'leaf_terminal_nodes\')\n        self.stats = {field:sum(p.get(field,0) for p in phases) for field in fields}\n        self.stats[\'nodes\'] += proof_stats[\'nodes\']\n        self.stats.update(depth=max((p[\'depth\'] for p in phases),default=0), elapsed=elapsed,\n            value=value, proven_outcome=proven, proof_outcome=proof_won, proof_kind=\'win_loss_only\' if proof_won is not None else None,\n            timed_out=any(p[\'timed_out\'] for p in phases), nps=round(self.stats[\'nodes\']/max(elapsed,1e-9)),\n            tt_entries=len(self.normal.table), proof_entries=len(self.proofs), proof_rotations=self.proofs.rotations,\n            proof_eligible=eligible, proof_attempted=proof_attempted, proof_reused=proof_reused,\n            proof_seconds=proof_seconds, proof_stats=proof_stats,\n            proof_root_hit=proof_reused and proof_won is True,\n            iterations=phases[-1][\'iterations\'] if phases else [], phases=phases, pv=[move],\n            normal_table_limit=self.normal.config.tt_size, proof_table_limit=self.proofs.half*2)\n        return move\n\n\n_player = None\n\n\ndef configure(seconds=29.0, max_nodes=0):\n    global _player\n    _player = Searcher(Config(seconds=seconds,max_nodes=max_nodes))\n\n\ndef name():\n    return \'Selective endgame v1.2 (experimental)\'\n\n\ndef getMove(state):\n    global _player\n    if _player is None: _player = Searcher()\n    return _player.choose(state)\n\n\ndef getStats():\n    return dict(_player.stats) if _player else {}\n'),
    ('PhaseFeatures.py', '"""Cheap symmetry-invariant features for a learned future-score evaluator.\n\nAll signed features are Light minus Dark. No banked captures enter the vector.\nThe side-to-move features represent tempo, not the Light tie-breaking rule.\n"""\nfrom player_versions.verified_denial_08.GameCore import SQUARES, RAYS\n\nNAMES = (\'material\', \'largest\', \'combines\', \'captures\', \'best_capture\',\n         \'capture_coverage\', \'stacks\', \'safe_largest\', \'bonus_access\',\n         \'tempo\', \'tempo_capture\')\nKNOTS = (10, 23, 36)\n\n\ndef phase_mix(stones):\n    if stones <= KNOTS[0]: return (1.0, 0.0, 0.0)\n    if stones < KNOTS[1]:\n        t = (stones-KNOTS[0])/(KNOTS[1]-KNOTS[0])\n        return (1-t, t, 0.0)\n    t = min(1.0, (stones-KNOTS[1])/(KNOTS[2]-KNOTS[1]))\n    return (0.0, 1-t, t)\n\n\ndef raw_features(pos):\n    board = pos.board\n    sides = []\n    attacked = []\n    for side in (1, -1):\n        material = largest = combines = captures = best = stacks = 0\n        targets = set()\n        for i in SQUARES[side]:\n            size = board[i]\n            if not size: continue\n            material += size; stacks += 1\n            if size > largest: largest = size\n            for ray in RAYS[i][:4]:\n                for j in ray:\n                    if board[j]:\n                        combines += 1\n                        break\n            if size >= 2:\n                for ray in RAYS[i][4:]:\n                    gain = 0\n                    for j in ray[:size:2]:\n                        if 0 < board[j] < size:\n                            gain += board[j]+1; targets.add(j)\n                    if gain:\n                        captures += 1\n                        if gain > best: best = gain\n        sides.append((material, largest, combines, captures, best,\n                      sum(board[j] for j in targets), stacks))\n        attacked.append(targets)\n    light, dark = sides\n    values = [a-b for a,b in zip(light,dark)]\n    safe_light = max((board[i] for i in SQUARES[1] if i not in attacked[1]), default=0)\n    safe_dark = max((board[i] for i in SQUARES[-1] if i not in attacked[0]), default=0)\n    lm, dm = light[2]+light[3], dark[2]+dark[3]\n    access = (light[1]*(lm+1)-dark[1]*(dm+1))/(lm+dm+2)\n    values.extend((safe_light-safe_dark, access, pos.turn, pos.turn*(light[4]+dark[4])))\n    return tuple(values)\n\n\ndef vector(pos):\n    raw = raw_features(pos)\n    return tuple(weight*x for weight in phase_mix(sum(pos.board)) for x in raw)\n\n\ndef baseline_future(pos):\n    f = raw_features(pos)\n    return .12*f[0]+.08*f[1]+.02*(f[2]+f[3])+.14*f[4]\n\n\ndef canonical_board(board):\n    """Four color-preserving transforms, used offline only."""\n    return min(tuple(board[i] for i in order) for order in TRANSFORMS)\n\n\nTRANSFORMS = (\n    tuple(range(36)), tuple(reversed(range(36))),\n    tuple((i%6)*6+i//6 for i in range(36)),\n    tuple((5-i%6)*6+5-i//6 for i in range(36)),\n)\n'),
    ('LearnedPhaseWeights.py', "# Generated by LearnedPhaseTraining.py; frozen before test metrics and matches.\nVERSION = 'learned-phase-01'\nCOEFFICIENTS = (0.6708373107321424, -0.6797992057239401, 0.5438140786073812, 0.4828683737330451, 0.24270998012579897, -0.12107190482822784, -1.2275965481739557, 0.2376061473395354, 0.7043841381247462, 0.28501643562117357, 0.04575885037324532, 0.9944192695255794, -0.36554692768986, 0.22506017914548393, -0.004874756644495333, 0.156086012742702, 0.3090591287431439, -1.0784098433252536, -0.06245168083041896, 1.3384019625169579, 0.4827587108841183, 0.07011975972733758, 0.63164674126041, 1.3156495656045695, 0.3199552885255473, -0.0815203187133797, -0.0864312779504457, 0.5323585998473792, -1.2204518429267834, -0.47603678438811686, -1.3175694588609517, 0.7554691129059499, 0.03382349493970249)\n"),
    ('LearnedPhasePlayer.py', '"""Experimental learned evaluation on the unchanged integrated v1/v5 search.\n\nStandard-library runtime. No training, disk database, or network use in a turn.\nThe terminal win/tie convention and bounded exact outcome solver are inherited.\n"""\nfrom player_versions.verified_denial_08.PhaseFeatures import raw_features, phase_mix, NAMES\nfrom player_versions.verified_denial_08.LearnedPhaseWeights import COEFFICIENTS, VERSION\nfrom player_versions.verified_denial_08.SelectiveEndgamePlayer import Searcher as Integrated, Config, _Guidance\n\nWIDTH = len(NAMES)\nif len(COEFFICIENTS) != 3*WIDTH:\n    raise ValueError(\'Feature/model dimension mismatch\')\n\n# Phase interpolation depends only on the remaining stones, not the clock.\nWEIGHTS = tuple(tuple(sum(mix[k]*COEFFICIENTS[k*WIDTH+j] for k in range(3))\n                      for j in range(WIDTH)) for mix in map(phase_mix,range(37)))\n\n\ndef future_margin(pos):\n    stones = sum(pos.board)\n    estimate = sum(w*x for w,x in zip(WEIGHTS[stones],raw_features(pos)))\n    # A bounded heuristic remains an estimate; it never creates a proof flag.\n    return max(-stones,min(stones,estimate))\n\n\nclass LearnedGuidance(_Guidance):\n    def evaluate(self,pos):\n        self.stats[\'eval_calls\'] += 1\n        return pos.turn*(100*pos.diff+round(100*future_margin(pos)))\n\n\nclass Searcher(Integrated):\n    def __init__(self,config=None,proof_capacity=100000):\n        super().__init__(config,proof_capacity)\n        self.normal = LearnedGuidance(self.normal.config)\n\n    def choose(self,state):\n        move = super().choose(state)\n        self.stats[\'evaluation_version\'] = VERSION\n        return move\n\n\n_player = None\n\n\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player = Searcher(Config(seconds=seconds,max_nodes=max_nodes))\n\n\ndef name(): return \'Learned phase evaluation 01 (experimental)\'\n\n\ndef getMove(state):\n    global _player\n    if _player is None: configure()\n    return _player.choose(state)\n\n\ndef getStats(): return dict(_player.stats) if _player else {}\n'),
    ('ProofGuardPlayer.py', '"""Use completed root-child proofs when the integrated solver runs out of time.\n\nThe frozen learned evaluation and original TT policy are unchanged. Prefer a\nproved win; exclude proved losing root moves only while another move is not\nproved losing. If all moves are known losses, retain ordinary margin search.\nNo heuristic value is converted into a proof or an exact numeric margin.\n"""\nfrom player_versions.verified_denial_08.GameCore import from_state, generate\nfrom player_versions.verified_denial_08.LearnedPhasePlayer import Searcher as Learned, LearnedGuidance, Config\nfrom player_versions.verified_denial_08.SelectiveEndgamePlayer import proof_key, unpack\n\n\nclass GuardGuidance(LearnedGuidance):\n    def __init__(self, config, proofs):\n        super().__init__(config)\n        self.proofs = proofs\n\n    def _start(self, seconds=None):\n        super()._start(seconds)\n        self.filtered = False\n        self.excluded = set()\n\n    def _order(self, pos, edges, preferred, ply):\n        if ply == 0:\n            kept = []\n            rejected = []\n            for edge in edges:\n                fact = self.proofs.get(proof_key(edge.child))\n                if fact is not None and unpack(fact)[0]:\n                    rejected.append(edge.move)\n                else:\n                    kept.append(edge)\n            if kept and rejected:\n                edges = kept\n                self.filtered = True\n                self.excluded.update(rejected)\n        return super()._order(pos, edges, preferred, ply)\n\n    def choose(self, state):\n        move = super().choose(state)\n        if self.filtered:\n            # The selected subset can establish an outcome, but cannot claim\n            # the best numerical losing margin across excluded alternatives.\n            # No descendant search can revisit the root in this acyclic game.\n            self.table.pop(from_state(state), None)\n        self.stats[\'root_proved_losses_excluded\'] = len(self.excluded)\n        return move\n\n\nclass Searcher(Learned):\n    def __init__(self, config=None, proof_capacity=100000):\n        super().__init__(config, proof_capacity)\n        self.normal = GuardGuidance(self.normal.config, self.proofs)\n\n    def choose(self, state):\n        pos = from_state(state)\n        for edge in generate(pos):\n            fact = self.proofs.get(proof_key(edge.child))\n            if fact is not None and not unpack(fact)[0]:\n                self.proofs.put(proof_key(pos), True, edge.move)\n                break\n        move = super().choose(state)\n        self.stats[\'root_proved_losses_excluded\'] = max(\n            (p.get(\'root_proved_losses_excluded\', 0) for p in self.stats[\'phases\']), default=0)\n        self.stats[\'search_version\'] = \'root-proof-guard-01\'\n        return move\n\n\n_player = None\ndef configure(seconds=29.0, max_nodes=0):\n    global _player\n    _player = Searcher(Config(seconds=seconds, max_nodes=max_nodes))\ndef name(): return \'Learned evaluator with completed-root-proof guard (experimental)\'\ndef getMove(state):\n    global _player\n    if _player is None: configure()\n    return _player.choose(state)\ndef getStats(): return dict(_player.stats) if _player else {}\n'),
