    ('VerifiedAvoidancePlayer.py', '"""Learned evaluation + root proof guard + verified outcome reuse before heuristic search.\n\nThe compact offline book stores proved thresholds, never patterns learned from\ngame winners. It has no network or disk-database dependency and fits inside the\nexisting 100k outcome-entry allowance together with the live proof cache.\n"""\nfrom player_versions.verified_denial_08.GameCore import from_state\nfrom player_versions.verified_denial_08.LearnedPhasePlayer import Config, LearnedGuidance\nfrom player_versions.verified_denial_08.ProofGuardPlayer import Searcher as Guard, GuardGuidance\nfrom player_versions.verified_denial_08.SelectiveEndgamePlayer import ProofCache, proof_key, unpack, WIN_BIT, NO_MOVE\nfrom player_versions.verified_denial_08.VerifiedOutcomeBook import RECORDS, VERSION\nfrom player_versions.verified_denial_08.challengers.LeafV5 import WIN\n\n\ndef lookup(key):\n    row = RECORDS.get(key[:37])\n    if row is None: return None\n    low, light_move, high, dark_move = row; diff = key[37] - 36\n    if low is not None and diff >= low: light_wins, move = True, light_move\n    elif high is not None and diff <= high: light_wins, move = False, dark_move\n    else: return None\n    won = light_wins if key[36] else not light_wins\n    return (WIN_BIT if won else 0) | (NO_MOVE if move is None else move)\n\n\nclass IndexedProofs(ProofCache):\n    def __init__(self, capacity):\n        super().__init__(capacity); self.book_hits = 0\n\n    def get(self, key):\n        if key == getattr(self, \'suppressed_root\', None): return None\n        value = super().get(key)\n        if value is not None: return value\n        value = lookup(key)\n        if value is not None: self.book_hits += 1\n        return value\n\n\nclass PreventionGuidance(GuardGuidance):\n    def _order(self,pos,edges,preferred,ply):\n        if self.root_already_lost:\n            return LearnedGuidance._order(self,pos,edges,preferred,ply)\n        return super()._order(pos,edges,preferred,ply)\n\n    def _start(self, seconds=None):\n        super()._start(seconds)\n        self.stats.update(prevention_hits=0, prevention_win_hits=0, prevention_loss_hits=0)\n\n    def _search(self, pos, depth, alpha, beta, ply=0):\n        self._check()\n        if not self.root_already_lost:\n            fact = self.proofs.get(proof_key(pos))\n            if fact is not None:\n                self.stats[\'nodes\'] += 1; self.stats[\'prevention_hits\'] += 1\n                won, _ = unpack(fact)\n                self.stats[\'prevention_win_hits\' if won else \'prevention_loss_hits\'] += 1\n                return WIN if won else -WIN\n        return super()._search(pos, depth, alpha, beta, ply)\n\n\nclass Searcher(Guard):\n    def __init__(self, config=None, proof_capacity=100000):\n        super().__init__(config,proof_capacity)\n        if proof_capacity <= len(RECORDS) + 2: raise ValueError(\'Outcome capacity too small for the frozen book\')\n        self.proofs = IndexedProofs(proof_capacity-len(RECORDS))\n        self.normal = PreventionGuidance(self.normal.config,self.proofs)\n\n    def choose(self,state):\n        pos = from_state(state); fact = self.proofs.get(proof_key(pos))\n        self.normal.root_already_lost = fact is not None and not unpack(fact)[0]\n        # Some certificates prove a win without retaining a move. They are\n        # sufficient inside search but cannot be an instant root response.\n        self.proofs.suppressed_root = proof_key(pos) if fact is not None and unpack(fact) == (True,None) else None\n        before = self.proofs.book_hits\n        try: move = super().choose(state)\n        finally: self.proofs.suppressed_root = None\n        for key in (\'prevention_hits\',\'prevention_win_hits\',\'prevention_loss_hits\'):\n            self.stats[key] = sum(p.get(key,0) for p in self.stats[\'phases\'])\n        self.stats.update(search_version=\'verified-prevention-01\',book_version=VERSION,\n            book_hits=self.proofs.book_hits-before, book_entries=len(RECORDS),\n            total_outcome_entries=len(self.proofs)+len(RECORDS),\n            normal_value_semantics=\'Heuristic scores or proved outcome anchors; not exact final margins.\')\n        return move\n\n\n_player = None\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player = Searcher(Config(seconds=seconds,max_nodes=max_nodes))\ndef name(): return \'Learned player with verified loss prevention\'\ndef getMove(state):\n    global _player\n    if _player is None: configure()\n    return _player.choose(state)\ndef getStats(): return dict(_player.stats) if _player else {}\n'),
    ('RaceFeatures.py', '"""Legacy features plus general combine-reserve/bonus-race estimates.\n\nConnected components use legal diagonal combine links. Without captures, a\ncomponent can be merged into one stack. Captures can change this graph, so the\nreserve and bonus-race values are evaluation features, never outcome proofs.\n"""\nfrom player_versions.verified_denial_08.GameCore import SQUARES, RAYS\nfrom player_versions.verified_denial_08.PhaseFeatures import NAMES as LEGACY_NAMES\n\nNAMES=LEGACY_NAMES+(\'combine_reserve\',\'component_mass\',\'quiet_race_bonus\',\'isolated_mass\')\n\n\ndef raw_features(pos):\n    board=pos.board;parents=list(range(36));sides=[];attacked=[];reserves=[];masses=[];isolated=[]\n    for side in (1,-1):\n        material=largest=combines=captures=best=stacks=0;targets=set()\n        for i in SQUARES[side]:\n            size=board[i]\n            if not size:continue\n            material+=size;stacks+=1\n            if size>largest:largest=size\n            for ray in RAYS[i][:4]:\n                for j in ray:\n                    if board[j]:\n                        combines+=1\n                        if i<j:\n                            a,b=i,j\n                            while parents[a]!=a:a=parents[a]\n                            while parents[b]!=b:b=parents[b]\n                            if a!=b:parents[b]=a\n                        break\n            if size>=2:\n                for ray in RAYS[i][4:]:\n                    gain=0\n                    for j in ray[:size:2]:\n                        if 0<board[j]<size:gain+=board[j]+1;targets.add(j)\n                    if gain:\n                        captures+=1\n                        if gain>best:best=gain\n        sides.append((material,largest,combines,captures,best,sum(board[j] for j in targets),stacks));attacked.append(targets)\n        groups={};counts={}\n        for i in SQUARES[side]:\n            if board[i]:\n                root=i\n                while parents[root]!=root:root=parents[root]\n                groups[root]=groups.get(root,0)+board[i];counts[root]=counts.get(root,0)+1\n        reserves.append(stacks-len(groups));masses.append(max(groups.values(),default=0))\n        isolated.append(sum(m for k,m in groups.items() if counts[k]==1))\n    light,dark=sides;values=[a-b for a,b in zip(light,dark)]\n    safe_light=max((board[i] for i in SQUARES[1] if i not in attacked[1]),default=0)\n    safe_dark=max((board[i] for i in SQUARES[-1] if i not in attacked[0]),default=0)\n    lm,dm=light[2]+light[3],dark[2]+dark[3]\n    access=(light[1]*(lm+1)-dark[1]*(dm+1))/(lm+dm+2)\n    values.extend((safe_light-safe_dark,access,pos.turn,pos.turn*(light[4]+dark[4])))\n    light_last=reserves[0]>reserves[1] or (reserves[0]==reserves[1] and pos.turn==-1)\n    bonus=(masses[0] if light_last else -masses[1])/(1+light[3]+dark[3])\n    values.extend((reserves[0]-reserves[1],masses[0]-masses[1],bonus,isolated[0]-isolated[1]))\n    return tuple(values)\n'),
    ('RaceWeights.py', '"""Frozen exact-label topology residual; no opponent-specific parameters."""\nVERSION="race-calibration-04"\nDELTA=(0.0008535006759793685, -0.18816609246415708, -0.16207744263872426, -0.11441895196778601, 0.07143854749093762, 0.41464488249153275, 0.3801331481542888, 0.07726211958699498, -0.22295629565716102, 0.2645456721047843, 0.2297411012850026, -0.2735620858562881, 0.026888084086166632, 0.5412999987068124, -0.13330617546439685)\n'),
    ('RacePlayer.py', '"""Successful learned foundation plus verified-data bonus-race evaluation."""\nfrom player_versions.verified_denial_08.LearnedPhasePlayer import WEIGHTS, LearnedGuidance\nfrom player_versions.verified_denial_08.RaceFeatures import raw_features\nfrom player_versions.verified_denial_08.RaceWeights import DELTA, VERSION\nfrom player_versions.verified_denial_08.VerifiedAvoidancePlayer import Searcher as Prevention, PreventionGuidance, Config\n\nWEIGHT_TABLE=tuple(tuple(w+max(0,min(1,(24-s)/8))*d for w,d in zip(tuple(row)+(0,)*4,DELTA)) for s,row in enumerate(WEIGHTS))\n\n\nclass Guidance(PreventionGuidance):\n    def evaluate(self,pos):\n        stones=sum(pos.board)\n        if stones>=24:return LearnedGuidance.evaluate(self,pos)\n        self.stats[\'eval_calls\']+=1\n        future=sum(w*x for w,x in zip(WEIGHT_TABLE[stones],raw_features(pos)))\n        return pos.turn*(100*pos.diff+round(100*max(-stones,min(stones,future))))\n\n\nclass Searcher(Prevention):\n    def __init__(self,config=None,proof_capacity=100000):\n        super().__init__(config,proof_capacity)\n        self.normal=Guidance(self.normal.config,self.proofs)\n\n    def choose(self,state):\n        move=super().choose(state)\n        self.stats[\'evaluation_version\']=VERSION;self.stats[\'search_version\']=VERSION\n        return move\n\n\n_player=None\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player=Searcher(Config(seconds=seconds,max_nodes=max_nodes))\ndef name():return \'Learned player with calibrated move reserves\'\ndef getMove(state):\n    global _player\n    if _player is None:configure()\n    return _player.choose(state)\ndef getStats():return dict(_player.stats) if _player else {}\n'),
    ('EfficientPreventionPlayer.py', '"""Same learned policy and proof guard; avoid redundant search work.\n\nMove descriptors defer board copies until a branch is visited. Quiet ordering\nis algebraically identical to V1/V5. A bounded cache reuses the unchanged\nrounded future-margin estimate, independent of banked capture scores.\nNo selective pruning, retraining, or new book knowledge.\n"""\nimport time\nfrom player_versions.verified_denial_08.GameCore import Position, RAYS, SQUARES\nfrom player_versions.verified_denial_08.LearnedPhasePlayer import future_margin, Config\nfrom player_versions.verified_denial_08.VerifiedAvoidancePlayer import Searcher as Base, PreventionGuidance\nfrom player_versions.verified_denial_08.SelectiveEndgamePlayer import proof_key, unpack\nfrom player_versions.verified_denial_08.challengers.LeafV5 import WIN, INF, EXACT, LOWER, UPPER, has_legal_move\n\n\ndef descriptors(pos):\n    """(move, gain, combine target or sow path), professor order."""\n    board,side,_=pos\n    result=[]\n    for i in SQUARES[side]:\n        size=board[i]\n        if not size:continue\n        for d,ray in enumerate(RAYS[i][:4]):\n            for j in ray:\n                if board[j]:\n                    result.append((i*8+d,0,j));break\n        if size<2:continue\n        for d in range(4,8):\n            path=RAYS[i][d][:size]\n            gain=sum(board[j]+1 for j in path[::2] if 0<board[j]<size)\n            if gain:result.append((i*8+d,gain,path))\n    return result\n\n\ndef advance(pos, item):\n    move,gain,target=item;source=move//8\n    b=list(pos.board);size=b[source]\n    if not gain:\n        b[target]+=size;b[source]=0\n    else:\n        b[source]=size-len(target)\n        for offset,j in enumerate(target):\n            b[j]=0 if offset%2==0 and 0<pos.board[j]<size else pos.board[j]+1\n    return Position(tuple(b),-pos.turn,pos.diff+pos.turn*gain)\n\n\nclass EfficientGuidance(PreventionGuidance):\n    def __init__(self,config,proofs):\n        super().__init__(config,proofs)\n        self.eval_new={};self.eval_old={}\n        self.eval_capacity=25000\n\n    def _start(self,seconds=None):\n        super()._start(seconds)\n        self.stats.update(eval_cache_hits=0,child_boards_built=0,legal_descriptors=0)\n\n    def evaluate(self,pos):\n        self.stats[\'eval_calls\']+=1\n        key=(pos.board,pos.turn)\n        value=self.eval_new.get(key)\n        if value is None:value=self.eval_old.get(key)\n        if value is None:\n            value=round(100*future_margin(pos))\n            if len(self.eval_new)>=self.eval_capacity//2:\n                self.eval_old=self.eval_new;self.eval_new={}\n            self.eval_new[key]=value\n        else:self.stats[\'eval_cache_hits\']+=1\n        return pos.turn*(100*pos.diff+value)\n\n    def _ordered_descriptors(self,pos,moves,preferred,ply):\n        board=pos.board;largest=max(board[i] for i in SQUARES[pos.turn])\n        killers=self.killers.get(ply,())\n        def key(item):\n            move,gain,target=item\n            score=self.history.get((pos.turn,move),0)\n            if move==preferred:score+=10000000\n            score+=gain*10000\n            if move in killers:score+=1000\n            if not gain:score+=4*max(largest,board[move//8]+board[target])\n            return score\n        return sorted(moves,key=key,reverse=True)\n\n    def _search(self,pos,depth,alpha,beta,ply=0):\n        self._check();self.stats[\'nodes\']+=1\n        if not self.root_already_lost:\n            fact=self.proofs.get(proof_key(pos))\n            if fact is not None:\n                self.stats[\'prevention_hits\']+=1\n                won,_=unpack(fact)\n                self.stats[\'prevention_win_hits\' if won else \'prevention_loss_hits\']+=1\n                return WIN if won else -WIN\n        original_alpha,original_beta=alpha,beta\n        entry=self.table.get(pos) if self.config.tt else None\n        preferred=entry[3] if entry else None\n        if entry:\n            self.stats[\'tt_hits\']+=1\n            if entry[0]>=depth:\n                _,value,flag,_=entry\n                if flag==EXACT:return value\n                if flag==LOWER:alpha=max(alpha,value)\n                else:beta=min(beta,value)\n                if alpha>=beta:\n                    self.stats[\'tt_cutoffs\']+=1;return value\n        if depth==0:\n            self.stats[\'leaf_probes\']+=1\n            if has_legal_move(pos):return self.evaluate(pos)\n            self.stats[\'terminal_nodes\']+=1;self.stats[\'leaf_terminal_nodes\']+=1\n            return self.terminal(pos)\n        moves=descriptors(pos)\n        self.stats[\'legal_descriptors\']+=len(moves)\n        if not moves:\n            self.stats[\'terminal_nodes\']+=1;return self.terminal(pos)\n        best,best_move=-INF,None\n        for item in self._ordered_descriptors(pos,moves,preferred,ply):\n            move,gain,_=item\n            self.stats[\'child_boards_built\']+=1\n            value=-self._search(advance(pos,item),depth-1,-beta,-alpha,ply+1)\n            if value>best:best,best_move=value,move\n            alpha=max(alpha,value)\n            if alpha>=beta:\n                self.stats[\'cutoffs\']+=1\n                if not gain:\n                    k=(pos.turn,move);self.history[k]=self.history.get(k,0)+depth*depth\n                    old=self.killers.get(ply,());self.killers[ply]=(move,)+tuple(m for m in old if m!=move)[:1]\n                break\n        flag=UPPER if best<=original_alpha else LOWER if best>=original_beta else EXACT\n        self._store(pos,depth,best,flag,best_move)\n        return best\n\n    def _store(self,pos,depth,value,flag,move):\n        # Preserve V1/V5 admission policy for the isolated performance revision.\n        if self.config.tt and len(self.table)<self.config.tt_size:\n            self.table[pos]=(depth,value,flag,move)\n\n\nclass Searcher(Base):\n    def __init__(self,config=None,proof_capacity=100000):\n        super().__init__(config,proof_capacity)\n        self.normal=EfficientGuidance(self.normal.config,self.proofs)\n    def choose(self,state):\n        move=super().choose(state)\n        self.stats[\'search_version\']=\'efficient-prevention-04\'\n        for k in (\'eval_cache_hits\',\'child_boards_built\',\'legal_descriptors\'):\n            self.stats[k]=sum(p.get(k,0) for p in self.stats[\'phases\'])\n        self.stats[\'evaluation_cache_entries\']=len(self.normal.eval_new)+len(self.normal.eval_old)\n        return move\n\n_player=None\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player=Searcher(Config(seconds=seconds,max_nodes=max_nodes))\ndef name():return \'Learned prevention with deferred board construction\'\ndef getMove(state):\n    global _player\n    if _player is None:configure()\n    return _player.choose(state)\ndef getStats():return dict(_player.stats) if _player else {}\n'),
    ('EfficientRacePlayer.py', '"""Apply verified search-work savings to the successful race-calibration candidate.\n\nThe race coefficients, original 33 learned coefficients, proof book and move\nordering are unchanged. This is a performance revision, not a new strategy.\n"""\nfrom player_versions.verified_denial_08.EfficientPreventionPlayer import Searcher as Efficient, EfficientGuidance, Config\nfrom player_versions.verified_denial_08.RacePlayer import WEIGHT_TABLE, raw_features, VERSION\n\n\nclass Guidance(EfficientGuidance):\n    def evaluate(self,pos):\n        stones=sum(pos.board)\n        if stones>=24:return super().evaluate(pos)\n        self.stats[\'eval_calls\']+=1\n        key=(pos.board,pos.turn);value=self.eval_new.get(key)\n        if value is None:value=self.eval_old.get(key)\n        if value is None:\n            future=sum(w*x for w,x in zip(WEIGHT_TABLE[stones],raw_features(pos)))\n            value=round(100*max(-stones,min(stones,future)))\n            if len(self.eval_new)>=self.eval_capacity//2:\n                self.eval_old=self.eval_new;self.eval_new={}\n            self.eval_new[key]=value\n        else:self.stats[\'eval_cache_hits\']+=1\n        return pos.turn*(100*pos.diff+value)\n\n\nclass Searcher(Efficient):\n    def __init__(self,config=None,proof_capacity=100000):\n        super().__init__(config,proof_capacity)\n        self.normal=Guidance(self.normal.config,self.proofs)\n    def choose(self,state):\n        move=super().choose(state)\n        self.stats.update(search_version=\'efficient-race-05\',evaluation_version=VERSION)\n        return move\n\n_player=None\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player=Searcher(Config(seconds=seconds,max_nodes=max_nodes))\ndef name():return \'Race-calibrated learned player with efficient search\'\ndef getMove(state):\n    global _player\n    if _player is None:configure()\n    return _player.choose(state)\ndef getStats():return dict(_player.stats) if _player else {}\n'),
    ('ProofTransitionRacePlayer.py', '"""Preserve practical search when a loss is proved during the current turn.\n\nThe original wrapper checks loss status only at turn entry. A proof completed\nbetween guidance and fallback therefore left outcome anchors enabled, flattening\nall root choices to -WIN and ending fallback at depth one. Recheck at every\nnormal phase, and invalidate cached values whenever anchor semantics change.\n"""\nfrom player_versions.verified_denial_08.GameCore import from_state\nfrom player_versions.verified_denial_08.EfficientRacePlayer import Searcher as Efficient, Guidance as EfficientGuidance, Config\nfrom player_versions.verified_denial_08.SelectiveEndgamePlayer import proof_key, unpack\n\n\nclass Guidance(EfficientGuidance):\n    def __init__(self,config,proofs):\n        super().__init__(config,proofs);self.cache_lost_mode=False\n    def choose(self,state):\n        fact=self.proofs.get(proof_key(from_state(state)))\n        lost=fact is not None and not unpack(fact)[0]\n        changed=lost!=self.cache_lost_mode\n        if changed:self.table.clear()\n        self.root_already_lost=lost;self.cache_lost_mode=lost\n        move=super().choose(state)\n        self.stats.update(loss_mode_transition=changed,root_already_lost=lost)\n        return move\n\n\nclass Searcher(Efficient):\n    def __init__(self,config=None,proof_capacity=100000):\n        super().__init__(config,proof_capacity);self.normal=Guidance(self.normal.config,self.proofs)\n    def choose(self,state):\n        move=super().choose(state)\n        self.stats.update(search_version=\'proof-transition-race-06\',\n            loss_mode_transitions=sum(p.get(\'loss_mode_transition\',False) for p in self.stats[\'phases\']))\n        return move\n\n_player=None\ndef configure(seconds=29.0,max_nodes=0):\n    global _player\n    _player=Searcher(Config(seconds=seconds,max_nodes=max_nodes))\ndef name():return \'Race-calibrated player with proof transition repair\'\ndef getMove(state):\n    global _player\n    if _player is None:configure()\n    return _player.choose(state)\ndef getStats():return dict(_player.stats) if _player else {}\n'),
