def _load_frozen_player():
    # Independent imports under different filenames have independent caches.
    namespace = '_sean_gilbert_denial08_' + __name__.encode().hex()
    for filename, source in _SOURCES:
        name = namespace + '.' + filename[:-3].replace('/', '.')
        parts = name.split('.')
        for index in range(1, len(parts)):
            parent = '.'.join(parts[:index])
            if parent not in _sys.modules:
                package = _types.ModuleType(parent)
                package.__path__ = []
                package.__package__ = parent
                _sys.modules[parent] = package
                if index > 1:
                    setattr(_sys.modules['.'.join(parts[:index-1])], parts[index-1], package)
        module = _types.ModuleType(name)
        module.__file__ = __file__ + '::' + filename
        module.__package__ = name.rpartition('.')[0]
        _sys.modules[name] = module
        setattr(_sys.modules[module.__package__], parts[-1], module)
        source = source.replace('player_versions.verified_denial_08', namespace)
        exec(compile(source, module.__file__, 'exec'), module.__dict__)
    return _sys.modules[namespace + '.VerifiedDenial08']


_entry = _load_frozen_player()
del _SOURCES, _load_frozen_player


def name():
    """Return the name recorded by the game engine."""
    return "Sean Gilbert"


def getMove(state):
    """Select a legal move without changing the supplied game state."""
    return _entry.getMove(state)


# Optional laboratory hooks; the professor's engine does not need these.
configure = _entry.configure
getStats = _entry.getStats
Config = _entry.Config
Searcher = _entry.Searcher
